    [1, 2, 5],
    [7, 3, 6],
    [7, 6, 5]
]

# Expansion map: output 0-1 -> input 0, output 2 -> input 1, output 3-4 -> input 2
output_rows = []
for r in range(5):
    if r <= 1:
        output_rows.append(0)
    elif r == 2:
        output_rows.append(1)
    else:
        output_rows.append(2)

