    row = []
    for c in range(5):
        # Same for columns
        if c <= 1:
            in_col = 0
        elif c == 2:
            in_col = 1
        else:
            in_col = 2
        row.append(input_test[output_rows[r]][in_col])
    output_grid.append(row)

print("Predicted output:")
